/// <summary>
/// PaffH 23.02.23
/// build new NameAlias from 2 NameParts
/// </summary>
/// <param name = "_namePart1">NamePart 1</param>
/// <param name = "_namePart2">NamePart 2</param>
/// <returns>new NameAlias</returns>
public str buildNameAliasFromNameParts(str _namePart1, str _namePart2)
{
    return this.buildNameAlias(_namePart1, strLen(_namePart1), _namePart2, strLen(_namePart2));
}
